<body>
  <video class="background-video" autoplay muted loop playsinline>
    <source src="video.mp4" type="video/mp4">
  </video>

  <main class="hero">
    <h1>Explore Zeroh</h1>
    <button class="waitlist-button">Join Waitlist</button>
  </main>
</body>
</html>
```

